FOODS_BY_CITY=[
 {"name":"Kjötsúpa","name_en":"Icelandic Lamb Soup","name_fr":"Soupe islandaise à l'agneau","name_es":"Sopa islandesa de cordero","description":"Zuppa limpida e sostanziosa con agnello, patate, rape, carote e cavolo, cotta finché carne e ortaggi diventano teneri. È cucina domestica adatta al freddo: il sapore deve essere profondo ma semplice, senza salse pesanti.","description_en":"A clear, substantial soup of lamb, potatoes, turnips, carrots and cabbage, cooked until meat and vegetables are tender. It is cold-weather home cooking: deep yet simple, without heavy sauces.","description_fr":"Soupe claire et consistante d'agneau, pommes de terre, navets, carottes et chou, cuite jusqu'à tendreté. C'est une cuisine familiale pour le froid: profonde mais simple, sans sauces lourdes.","description_es":"Sopa clara y contundente de cordero, patata, nabo, zanahoria y col, cocida hasta que todo queda tierno. Es cocina casera para el frío: profunda pero sencilla, sin salsas pesadas.","ingredients":["agnello","patate","rape","carote","cavolo"],"ingredients_en":["lamb","potatoes","turnips","carrots","cabbage"],"ingredients_fr":["agneau","pommes de terre","navets","carottes","chou"],"ingredients_es":["cordero","patatas","nabos","zanahorias","col"],"places":["Icelandic Street Food Reykjavik","Cafe Loki Reykjavik","Salka Valka Reykjavik"]},
 {"name":"Plokkfiskur","name_en":"Icelandic Fish Stew","name_fr":"Ragout islandais de poisson","name_es":"Guiso islandés de pescado","description":"Merluzzo o eglefino viene sminuzzato con patate, cipolla e salsa bianca, poi servito con pane di segale. Nato per valorizzare il pesce avanzato, oggi è un comfort food cremoso in cui il sapore marino deve restare riconoscibile.","description_en":"Cod or haddock is flaked with potatoes, onion and white sauce, then served with rye bread. Born to use leftover fish, it is now creamy comfort food in which the seafood flavour should remain clear.","description_fr":"Cabillaud ou aiglefin est émietté avec pommes de terre, oignon et sauce blanche, puis servi avec du pain de seigle. Né pour utiliser les restes, c'est aujourd'hui un plat crémeux où le poisson doit rester net.","description_es":"Bacalao o eglefino se desmenuza con patata, cebolla y salsa blanca, y se sirve con pan de centeno. Nacido para aprovechar sobras, hoy es un plato cremoso donde el sabor del pescado debe seguir presente.","ingredients":["merluzzo","patate","cipolla","latte","pane di segale"],"ingredients_en":["cod","potatoes","onion","milk","rye bread"],"ingredients_fr":["cabillaud","pommes de terre","oignon","lait","pain de seigle"],"ingredients_es":["bacalao","patatas","cebolla","leche","pan de centeno"],"places":["Messinn Reykjavik","Matur og Drykkur Reykjavik","Cafe Loki Reykjavik"]},
 {"name":"Íslenskt lambakjöt","name_en":"Icelandic Lamb","name_fr":"Agneau islandais","name_es":"Cordero islandés","description":"L'agnello islandese, allevato all'aperto in estate, viene arrostito o grigliato con erbe, radici e salsa concentrata. La carne è magra ma saporita e dà il meglio con cottura rosata o lenta, non asciutta.","description_en":"Icelandic lamb, grazed outdoors in summer, is roasted or grilled with herbs, roots and reduced sauce. The meat is lean yet flavourful and works best pink or slowly cooked rather than dry.","description_fr":"L'agneau islandais, élevé dehors en été, est rôti ou grillé avec herbes, racines et jus réduit. La viande est maigre mais savoureuse et se déguste rosée ou longuement cuite, jamais sèche.","description_es":"El cordero islandés, criado al aire libre en verano, se asa con hierbas, raíces y salsa reducida. La carne es magra pero sabrosa y resulta mejor rosada o cocinada lentamente, nunca seca.","ingredients":["agnello islandese","erbe","ortaggi a radice","burro","fondo di carne"],"ingredients_en":["Icelandic lamb","herbs","root vegetables","butter","meat jus"],"ingredients_fr":["agneau islandais","herbes","légumes racines","beurre","jus de viande"],"ingredients_es":["cordero islandés","hierbas","raíces","mantequilla","jugo de carne"],"places":["Grillmarkadurinn Reykjavik","ROK Restaurant Reykjavik","Thrir Frakkar Reykjavik"]},
 {"name":"Pylsur","name_en":"Icelandic Hot Dog","name_fr":"Hot-dog islandais","name_es":"Perrito caliente islandés","description":"La salsiccia miscela soprattutto agnello con maiale e manzo ed è servita con cipolla cruda e croccante, ketchup, senape dolce e remoulade. Ordinata “eina með öllu” diventa lo spuntino urbano più riconoscibile e accessibile.","description_en":"The sausage blends mostly lamb with pork and beef and is served with raw and crispy onions, ketchup, sweet mustard and remoulade. Ordered “eina með öllu”, it becomes the city's most recognisable affordable snack.","description_fr":"La saucisse mêle surtout agneau, porc et bœuf, avec oignon cru et croustillant, ketchup, moutarde douce et rémoulade. Commandée «eina með öllu», c'est l'encas urbain le plus emblématique et abordable.","description_es":"La salchicha mezcla principalmente cordero con cerdo y ternera y se sirve con cebolla cruda y crujiente, kétchup, mostaza dulce y remoulade. Pedida “eina með öllu”, es el tentempié urbano más reconocible y económico.","ingredients":["agnello","maiale","manzo","cipolla","remoulade"],"ingredients_en":["lamb","pork","beef","onion","remoulade"],"ingredients_fr":["agneau","porc","bœuf","oignon","rémoulade"],"ingredients_es":["cordero","cerdo","ternera","cebolla","remoulade"],"places":["Baejarins Beztu Pylsur Reykjavik","Pylsuvagninn Laugardalur Reykjavik","Vikinga Pylsur Reykjavik"]},
 {"name":"Rúgbrauð","name_en":"Icelandic Rye Bread","name_fr":"Pain de seigle islandais","name_es":"Pan de centeno islandés","description":"Pane scuro, compatto e leggermente dolce, tradizionalmente cotto lentamente con il calore geotermico. Accompagna burro, pesce affumicato o plokkfiskur; la lunga cottura sviluppa note di melassa senza trasformarlo in un dolce.","description_en":"A dark, dense and gently sweet loaf traditionally slow-baked with geothermal heat. It accompanies butter, smoked fish or plokkfiskur; long baking develops molasses notes without turning it into cake.","description_fr":"Pain sombre, dense et légèrement sucré, traditionnellement cuit lentement grâce à la chaleur géothermique. Il accompagne beurre, poisson fumé ou plokkfiskur; la cuisson développe des notes de mélasse sans en faire un gâteau.","description_es":"Pan oscuro, denso y ligeramente dulce, tradicionalmente cocido lentamente con calor geotérmico. Acompaña mantequilla, pescado ahumado o plokkfiskur; la cocción desarrolla notas de melaza sin convertirlo en pastel.","ingredients":["farina di segale","farina di frumento","latticello","melassa","sale"],"ingredients_en":["rye flour","wheat flour","buttermilk","molasses","salt"],"ingredients_fr":["farine de seigle","farine de blé","babeurre","mélasse","sel"],"ingredients_es":["harina de centeno","harina de trigo","suero de leche","melaza","sal"],"places":["Cafe Loki Reykjavik","Sandholt Reykjavik","Braud & Co Reykjavik"]},
 {"name":"Skyr","name_en":"Skyr","name_fr":"Skyr","name_es":"Skyr","description":"Latticino fermentato molto proteico, denso come uno yogurt ma tecnicamente vicino a un formaggio fresco. Si mangia con panna, latte, frutti di bosco o granola; quello naturale permette di riconoscere meglio acidità e consistenza.","description_en":"A protein-rich cultured dairy product, thick like yoghurt but technically close to fresh cheese. It is eaten with cream, milk, berries or granola; plain skyr best reveals its acidity and texture.","description_fr":"Produit laitier fermenté riche en protéines, épais comme un yaourt mais techniquement proche d'un fromage frais. Il se mange avec crème, lait, baies ou granola; nature, il révèle mieux acidité et texture.","description_es":"Lácteo fermentado rico en proteínas, espeso como yogur pero técnicamente cercano a un queso fresco. Se toma con nata, leche, bayas o granola; natural permite apreciar mejor su acidez y textura.","ingredients":["latte scremato","fermenti","caglio"],"ingredients_en":["skimmed milk","cultures","rennet"],"ingredients_fr":["lait écrémé","ferments","présure"],"ingredients_es":["leche desnatada","fermentos","cuajo"],"places":["Cafe Loki Reykjavik","Sandholt Reykjavik","Reykjavik Roasters Reykjavik"]},
 {"name":"Kleinur","name_en":"Icelandic Twisted Doughnuts","name_fr":"Beignets torsadés islandais","name_es":"Rosquillas islandesas trenzadas","description":"Impasto profumato al cardamomo viene inciso, attorcigliato e fritto fino a formare un dolce asciutto e morbido. È meno zuccherino di una ciambella glassata e accompagna bene il caffè nelle panetterie tradizionali.","description_en":"Cardamom-scented dough is cut, twisted and fried into a soft, relatively dry pastry. Less sweet than a glazed doughnut, it pairs naturally with coffee in traditional bakeries.","description_fr":"Une pâte parfumée à la cardamome est découpée, torsadée puis frite en un beignet moelleux et assez sec. Moins sucré qu'un donut glacé, il accompagne naturellement le café.","description_es":"Una masa aromatizada con cardamomo se corta, retuerce y fríe hasta obtener un dulce tierno y relativamente seco. Menos dulce que un donut glaseado, acompaña muy bien al café.","ingredients":["farina","latticello","uova","cardamomo","olio"],"ingredients_en":["flour","buttermilk","eggs","cardamom","oil"],"ingredients_fr":["farine","babeurre","œufs","cardamome","huile"],"ingredients_es":["harina","suero de leche","huevos","cardamomo","aceite"],"places":["Sandholt Reykjavik","Bernhoftsbakari Reykjavik","Braud & Co Reykjavik"]},
 {"name":"Hákarl","name_en":"Fermented Shark","name_fr":"Requin fermenté","name_es":"Tiburón fermentado","description":"Carne di squalo della Groenlandia viene fatta fermentare e asciugare per eliminare le sostanze naturalmente tossiche. Si assaggia in piccoli cubi per il forte aroma ammoniacale: è soprattutto un'esperienza culturale, non un pasto quotidiano.","description_en":"Greenland shark is fermented and dried to remove naturally toxic compounds. It is sampled in tiny cubes because of its strong ammonia aroma: chiefly a cultural experience rather than an everyday meal.","description_fr":"La chair de requin du Groenland est fermentée puis séchée pour éliminer ses composés naturellement toxiques. Elle se goûte en petits cubes à cause de son fort arôme ammoniacal: c'est surtout une expérience culturelle.","description_es":"La carne de tiburón de Groenlandia se fermenta y seca para eliminar compuestos naturalmente tóxicos. Se prueba en cubos pequeños por su fuerte aroma amoniacal: es sobre todo una experiencia cultural, no una comida diaria.","ingredients":["squalo della Groenlandia","sale"],"ingredients_en":["Greenland shark","salt"],"ingredients_fr":["requin du Groenland","sel"],"ingredients_es":["tiburón de Groenlandia","sal"],"places":["Cafe Loki Reykjavik","Islenski Barinn Reykjavik","Thrir Frakkar Reykjavik"]},
]

CULTURE_FACTS=[
 fact("♨️",n("La piscina è un centro sociale","The pool is a social hub","La piscine est un centre social","La piscina es un centro social"),n("Le vasche geotermiche pubbliche sono luoghi quotidiani di conversazione, salute e incontro tra generazioni.","Public geothermal pools are everyday places for conversation, health and intergenerational encounters.","Les piscines géothermiques publiques sont des lieux quotidiens de conversation, santé et rencontre entre générations.","Las piscinas geotérmicas públicas son lugares cotidianos de conversación, salud y encuentro entre generaciones.")),
 fact("📚",n("Le saghe sono memoria e letteratura","The sagas are memory and literature","Les sagas sont mémoire et littérature","Las sagas son memoria y literatura"),n("I racconti medievali continuano a influenzare identità, nomi dei luoghi e modo di narrare il paese.","Medieval narratives continue to shape identity, place names and the way Iceland tells its story.","Les récits médiévaux continuent de façonner identité, noms de lieux et manière de raconter le pays.","Los relatos medievales siguen influyendo en la identidad, los topónimos y la forma de contar el país.")),
 fact("🌋",n("L'energia geotermica entra nella vita urbana","Geothermal energy enters urban life","La géothermie entre dans la vie urbaine","La geotermia entra en la vida urbana"),n("Riscaldamento, acqua calda, piscine e perfino alcuni marciapiedi sfruttano il calore del sottosuolo.","Heating, hot water, pools and even some pavements use heat from beneath the ground.","Chauffage, eau chaude, piscines et même certains trottoirs utilisent la chaleur du sous-sol.","Calefacción, agua caliente, piscinas e incluso algunas aceras aprovechan el calor del subsuelo.")),
 fact("🎶",n("La scena musicale supera le dimensioni della città","The music scene exceeds the city's size","La scène musicale dépasse la taille de la ville","La escena musical supera el tamaño de la ciudad"),n("Piccoli locali, festival e Harpa hanno prodotto una presenza internazionale sorprendente per una capitale così compatta.","Small venues, festivals and Harpa have produced a remarkable international presence for such a compact capital.","Petites salles, festivals et Harpa ont créé une présence internationale remarquable pour une capitale si compacte.","Pequeños locales, festivales y Harpa han creado una presencia internacional sorprendente para una capital tan compacta.")),
 fact("☕",n("Il caffè accompagna giornate lunghe e buie","Coffee accompanies long dark days","Le café accompagne les longues journées sombres","El café acompaña los días largos y oscuros"),n("Caffetterie e panetterie sono spazi di sosta importanti durante l'inverno e nella vita creativa del centro.","Cafés and bakeries are important winter refuges and spaces in downtown creative life.","Cafés et boulangeries sont des refuges hivernaux importants et des lieux de la vie créative du centre.","Cafeterías y panaderías son refugios invernales importantes y espacios de la vida creativa del centro.")),
 fact("🌊",n("Il porto precede la capitale moderna","The harbour predates the modern capital","Le port précède la capitale moderne","El puerto precede a la capital moderna"),n("Pesca e navigazione trasformarono un piccolo insediamento agricolo nel principale centro urbano islandese.","Fishing and navigation turned a small farming settlement into Iceland's principal urban centre.","Pêche et navigation transformèrent un petit établissement agricole en principal centre urbain islandais.","La pesca y la navegación transformaron un pequeño asentamiento agrícola en el principal centro urbano islandés.")),
 fact("🏠",n("Le case colorate rispondono anche al clima","Colourful houses also answer the climate","Les maisons colorées répondent aussi au climat","Las casas de colores también responden al clima"),n("Rivestimenti in lamiera proteggono molte strutture in legno, mentre il colore rende leggibili le strade nella luce nordica.","Corrugated metal protects many timber structures, while colour makes streets legible in Nordic light.","La tôle protège de nombreuses structures en bois, tandis que la couleur rend les rues lisibles sous la lumière nordique.","La chapa protege muchas estructuras de madera, mientras el color hace legibles las calles bajo la luz nórdica.")),
 fact("🗳️",n("Alþingi rivendica origini nel 930","Alþingi traces its origins to 930","L'Alþingi remonte à 930","El Alþingi remonta sus orígenes al 930"),n("L'assemblea medievale di Þingvellir è alla base della tradizione parlamentare oggi rappresentata nel centro di Reykjavík.","The medieval assembly at Þingvellir underpins the parliamentary tradition represented today in central Reykjavík.","L'assemblée médiévale de Þingvellir fonde la tradition parlementaire aujourd'hui représentée au centre de Reykjavík.","La asamblea medieval de Þingvellir sustenta la tradición parlamentaria hoy representada en el centro de Reikiavik.")),
 fact("🌌",n("L'aurora non è garantita in città","The aurora is never guaranteed in the city","L'aurore n'est jamais garantie en ville","La aurora nunca está garantizada en la ciudad"),n("Servono buio, cielo sereno e attività solare; Grótta riduce le luci ma il meteo resta decisivo.","Darkness, clear sky and solar activity are required; Grótta reduces light pollution but weather remains decisive.","Il faut obscurité, ciel clair et activité solaire; Grótta réduit les lumières mais la météo reste décisive.","Se necesitan oscuridad, cielo despejado y actividad solar; Grótta reduce la luz, pero el tiempo sigue siendo decisivo.")),
 fact("🐋",n("Le balene condividono la baia con la città","Whales share the bay with the city","Les baleines partagent la baie avec la ville","Las ballenas comparten la bahía con la ciudad"),n("Le uscite partono dal porto, ma gli avvistamenti dipendono da stagione, mare e comportamento degli animali.","Trips leave from the harbour, but sightings depend on season, sea conditions and animal behaviour.","Les sorties partent du port, mais les observations dépendent de la saison, de la mer et des animaux.","Las salidas parten del puerto, pero los avistamientos dependen de la temporada, el mar y el comportamiento animal.")),
 fact("🌈",n("L'inclusione è visibile nello spazio pubblico","Inclusion is visible in public space","L'inclusion est visible dans l'espace public","La inclusión es visible en el espacio público"),n("Pride, Rainbow Street e una vivace comunità LGBTQIA+ sono parte riconoscibile dell'identità contemporanea.","Pride, Rainbow Street and a lively LGBTQIA+ community are a visible part of contemporary identity.","Pride, Rainbow Street et une communauté LGBTQIA+ dynamique font partie de l'identité contemporaine visible.","Pride, Rainbow Street y una comunidad LGBTQIA+ activa son parte visible de la identidad contemporánea.")),
 fact("🌬️",n("Il vento cambia la percezione delle distanze","Wind changes how distance feels","Le vent change la perception des distances","El viento cambia la percepción de las distancias"),n("Percorsi brevi possono diventare impegnativi: abbigliamento a strati e controllo meteo contano più della sola temperatura.","Short routes can become demanding: layers and weather checks matter more than temperature alone.","De courts trajets peuvent devenir exigeants: couches de vêtements et météo comptent plus que la seule température.","Recorridos cortos pueden volverse exigentes: vestirse por capas y revisar el tiempo importa más que la temperatura.")),
]

CITY_INFO={"city":CITY_ID,"currency":"Corona islandese (ISK)","currency_en":"Icelandic króna (ISK)","currency_fr":"Couronne islandaise (ISK)","currency_es":"Corona islandesa (ISK)","language":"Islandese","language_en":"Icelandic","language_fr":"Islandais","language_es":"Islandés","english_level":"molto alto","english_note":"L'inglese è parlato fluentemente quasi ovunque nei servizi e nelle attività turistiche.","english_note_en":"English is spoken fluently almost everywhere in services and visitor businesses.","english_note_fr":"L'anglais est parlé couramment presque partout dans les services et activités touristiques.","english_note_es":"El inglés se habla con fluidez casi en todos los servicios y actividades turísticas.","timezone":"GMT (UTC+0) tutto l'anno, senza ora legale","voltage":"230 V, prese tipo F","water":"L'acqua fredda del rubinetto è potabile e di qualità eccellente; quella calda può avere odore di zolfo geotermico.","water_en":"Cold tap water is safe and excellent; hot water may smell of geothermal sulphur.","water_fr":"L'eau froide du robinet est potable et excellente; l'eau chaude peut sentir le soufre géothermique.","water_es":"El agua fría del grifo es potable y excelente; el agua caliente puede oler a azufre geotérmico.","tipping":"La mancia non è prevista né richiesta; il servizio è normalmente incluso nel prezzo.","tipping_en":"Tipping is neither expected nor required; service is normally included in the price.","tipping_fr":"Le pourboire n'est ni attendu ni obligatoire; le service est normalement inclus.","tipping_es":"La propina no se espera ni se exige; el servicio suele estar incluido.","emergency_numbers":[{"label":"Emergenze generali","label_en":"General emergency","label_fr":"Urgences générales","label_es":"Emergencias generales","number":"112"},{"label":"Informazioni condizioni stradali","label_en":"Road conditions information","label_fr":"Informations état des routes","label_es":"Información sobre carreteras","number":"1777"}],"transport_apps":[{"name":"Klappið","description":"Biglietti e informazioni per gli autobus Strætó nell'area della capitale.","description_en":"Tickets and information for Strætó buses in the capital area.","description_fr":"Billets et informations pour les bus Strætó de la région capitale.","description_es":"Billetes e información para los autobuses Strætó del área de la capital.","ios_url":"itms-apps://itunes.apple.com/search?term=Klappid&media=software","android_url":"https://play.google.com/store/search?q=Klappid&c=apps"}],"useful_apps":[{"name":"SafeTravel Iceland","description":"Avvisi ufficiali su meteo, strade e sicurezza per escursioni e spostamenti.","description_en":"Official weather, road and safety alerts for trips and travel.","description_fr":"Alertes officielles météo, routes et sécurité pour excursions et déplacements.","description_es":"Alertas oficiales de tiempo, carreteras y seguridad para excursiones y desplazamientos.","ios_url":"https://safetravel.is/","android_url":"https://safetravel.is/"},{"name":"Veður","description":"Previsioni e allerte dell'Ufficio Meteorologico Islandese.","description_en":"Forecasts and warnings from the Icelandic Met Office.","description_fr":"Prévisions et alertes de l'Office météorologique islandais.","description_es":"Previsiones y alertas de la Oficina Meteorológica de Islandia.","ios_url":"https://en.vedur.is/","android_url":"https://en.vedur.is/"}],"quick_tips":["Controlla sempre vento, pioggia e allerte: il meteo cambia più rapidamente della temperatura indicata.","Sugli autobus urbani non fare affidamento sui contanti; usa pagamento contactless o le soluzioni Klapp.","La linea 55 per Keflavík non è inclusa nella Reykjavík City Card.","Nelle piscine è obbligatoria la doccia completa senza costume prima di entrare in acqua.","Per Grótta verifica marea e chiusure stagionali; non attraversare verso il faro con acqua in salita."],"quick_tips_en":["Always check wind, rain and warnings: weather changes faster than the stated temperature.","Do not rely on cash on city buses; use contactless payment or Klapp solutions.","Bus 55 to Keflavík is not included in the Reykjavík City Card.","At pools, a full shower without swimwear is compulsory before entering the water.","For Grótta, check tides and seasonal closures; never cross to the lighthouse on a rising tide."],"quick_tips_fr":["Vérifiez toujours vent, pluie et alertes: la météo change plus vite que la température annoncée.","Ne comptez pas sur les espèces dans les bus; utilisez le sans contact ou les solutions Klapp.","La ligne 55 pour Keflavík n'est pas incluse dans la Reykjavík City Card.","Dans les piscines, la douche complète sans maillot est obligatoire avant l'entrée dans l'eau.","Pour Grótta, vérifiez marées et fermetures saisonnières; ne traversez jamais lorsque la marée monte."],"quick_tips_es":["Comprueba siempre viento, lluvia y alertas: el tiempo cambia más rápido que la temperatura indicada.","No dependas del efectivo en autobuses urbanos; usa pago sin contacto o soluciones Klapp.","La línea 55 a Keflavík no está incluida en la Reykjavík City Card.","En las piscinas es obligatoria una ducha completa sin bañador antes de entrar al agua.","Para Grótta, comprueba mareas y cierres estacionales; nunca cruces hacia el faro con la marea subiendo."]}

NEIGHBORHOODS=[
 neighborhood(11,CITY_ID,n("Miðborg, centro 101","Miðborg, Downtown 101","Miðborg, centre 101","Miðborg, centro 101"),n("Pro: attrazioni, ristoranti e vita serale raggiungibili a piedi. Pro: partenze comode per tour e porto. Contro: prezzi molto elevati. Contro: rumore nel fine settimana e parcheggio difficile.","Pros: sights, restaurants and nightlife are walkable. Pros: convenient tour and harbour departures. Cons: very high prices. Cons: weekend noise and difficult parking.","Avantages: sites, restaurants et sorties à pied. Avantages: départs pratiques pour excursions et port. Inconvénients: prix très élevés. Inconvénients: bruit le week-end et stationnement difficile.","Ventajas: monumentos, restaurantes y vida nocturna a pie. Ventajas: salidas cómodas para excursiones y puerto. Desventajas: precios muy elevados. Desventajas: ruido el fin de semana y aparcamiento difícil."),["centrale","vita notturna","attrazioni"]),
 neighborhood(12,CITY_ID,n("Vesturbær","Vesturbær","Vesturbær","Vesturbær"),n("Pro: quartiere residenziale vicino a centro, piscina e mare. Pro: caffè locali e maggiore tranquillità. Contro: meno hotel e ristoranti serali. Contro: le estremità occidentali richiedono autobus o lunghe camminate.","Pros: residential district near centre, pool and sea. Pros: local cafés and greater quiet. Cons: fewer hotels and evening restaurants. Cons: western edges require buses or long walks.","Avantages: quartier résidentiel près du centre, de la piscine et de la mer. Avantages: cafés locaux et calme. Inconvénients: moins d'hôtels et restaurants le soir. Inconvénients: l'ouest exige bus ou longues marches.","Ventajas: barrio residencial cerca del centro, piscina y mar. Ventajas: cafeterías locales y mayor tranquilidad. Desventajas: menos hoteles y restaurantes nocturnos. Desventajas: el extremo oeste requiere autobús o largas caminatas."),["residenziale","lungomare","tranquillo"]),
 neighborhood(13,CITY_ID,n("Hlíðar","Hlíðar","Hlíðar","Hlíðar"),n("Pro: posizione intermedia tra centro, Perlan e Laugardalur. Pro: ambiente locale e collegamenti autobus. Contro: poche attrazioni immediate. Contro: vento e salite rendono alcune camminate meno comode.","Pros: intermediate position between downtown, Perlan and Laugardalur. Pros: local atmosphere and bus links. Cons: few immediate sights. Cons: wind and slopes make some walks less convenient.","Avantages: position intermédiaire entre centre, Perlan et Laugardalur. Avantages: ambiance locale et bus. Inconvénients: peu de sites immédiats. Inconvénients: vent et pentes compliquent certaines marches.","Ventajas: posición intermedia entre centro, Perlan y Laugardalur. Ventajas: ambiente local y autobuses. Desventajas: pocos lugares inmediatos. Desventajas: viento y pendientes dificultan algunos paseos."),["locale","trasporti","residenziale"]),
 neighborhood(14,CITY_ID,n("Laugardalur","Laugardalur","Laugardalur","Laugardalur"),n("Pro: piscine, verde e servizi adatti alle famiglie. Pro: strutture sportive e autobus frequenti. Contro: centro non raggiungibile comodamente a piedi da ogni punto. Contro: vita serale limitata.","Pros: pools, greenery and family facilities. Pros: sport venues and frequent buses. Cons: downtown is not comfortably walkable from every point. Cons: limited nightlife.","Avantages: piscines, verdure et services familiaux. Avantages: équipements sportifs et bus fréquents. Inconvénients: centre pas toujours accessible à pied. Inconvénients: vie nocturne limitée.","Ventajas: piscinas, zonas verdes y servicios familiares. Ventajas: instalaciones deportivas y autobuses frecuentes. Desventajas: el centro no siempre queda cómodo a pie. Desventajas: vida nocturna limitada."),["famiglie","verde","trasporti"]),
 neighborhood(15,CITY_ID,n("Grandi e Porto Vecchio","Grandi and Old Harbour","Grandi et Vieux-Port","Grandi y Puerto Viejo"),n("Pro: whale watching, musei e ristoranti di pesce vicini. Pro: centro raggiungibile a piedi. Contro: attività portuale e cantieri possono creare rumore. Contro: atmosfera meno residenziale.","Pros: whale watching, museums and seafood nearby. Pros: downtown is walkable. Cons: harbour work and construction can create noise. Cons: less residential atmosphere.","Avantages: baleines, musées et poisson à proximité. Avantages: centre accessible à pied. Inconvénients: port et travaux peuvent être bruyants. Inconvénients: ambiance moins résidentielle.","Ventajas: observación de ballenas, museos y pescado cerca. Ventajas: centro accesible a pie. Desventajas: puerto y obras pueden generar ruido. Desventajas: ambiente menos residencial."),["porto","ristoranti","musei"]),
 neighborhood(16,CITY_ID,n("Kópavogur","Kópavogur","Kópavogur","Kópavogur"),n("Pro: alloggi spesso più spaziosi e accesso alla Sky Lagoon. Pro: atmosfera residenziale e servizi completi. Contro: dipendenza dagli autobus o dall'auto. Contro: meno identità turistica e distanza dal centro storico.","Pros: often roomier lodging and access to Sky Lagoon. Pros: residential setting and complete services. Cons: dependence on buses or car. Cons: less visitor atmosphere and distance from historic centre.","Avantages: logements souvent plus spacieux et accès à Sky Lagoon. Avantages: cadre résidentiel et services complets. Inconvénients: dépendance aux bus ou à la voiture. Inconvénients: moins d'ambiance touristique et loin du centre historique.","Ventajas: alojamientos a menudo más amplios y acceso a Sky Lagoon. Ventajas: entorno residencial y servicios completos. Desventajas: dependencia del autobús o coche. Desventajas: menos ambiente turístico y distancia del centro histórico."),["residenziale","spa","trasporti"]),
]
